window.ScripturaLexicons.DGP.cardsHtml += "<article id=\"entry-dgp-25101\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Λήρισαι, Ληρισαῖος</h1><div class=\"entry-meta\"><span>DGP · ordem 494 na letra λ · nº geral 25101</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. = Λάρισα, Λαρισαῖος.</p></section></article>\n<article id=\"entry-dgp-25102\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λῆρος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 495 na letra λ · nº geral 25102</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 disparate; tagarelice; tolice; mesquinharia 2 divagação 3 Medic. delírio 4 pessoa tola; pateta 5 bagatela; bugiganga; ninharia; quinquilharia.</p></section></article>\n<article id=\"entry-dgp-25103\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ληρώδης, ης, ες</h1><div class=\"entry-meta\"><span>DGP · ordem 496 na letra λ · nº geral 25103</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">tolo; tagarela; pateta. 〈λῆρος, -ωδης〉</p></section></article>\n<article id=\"entry-dgp-25104\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λῇς</h1><div class=\"entry-meta\"><span>DGP · ordem 497 na letra λ · nº geral 25104</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. λάω2.</p></section></article>\n<article id=\"entry-dgp-25105\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λησμοσύνη, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 498 na letra λ · nº geral 25105</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">poét. esquecimento. 〈λήθω〉</p></section></article>\n<article id=\"entry-dgp-25106\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λῃστάρχης, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 499 na letra λ · nº geral 25106</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">chefe de bandidos ou de piratas. 〈λῃσ­τής, ἄρχω〉</p></section></article>\n<article id=\"entry-dgp-25107\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λῃστεία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 500 na letra λ · nº geral 25107</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">banditismo; pirataria. 〈λῃστεύω〉</p></section></article>\n<article id=\"entry-dgp-25108\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λῃστείρα, ας</h1><div class=\"entry-meta\"><span>DGP · ordem 501 na letra λ · nº geral 25108</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fem.) de piratas (nau). 〈λῃστής〉</p></section></article>\n<article id=\"entry-dgp-25109\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λῃστεύω</h1><div class=\"entry-meta\"><span>DGP · ordem 502 na letra λ · nº geral 25109</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. λῃστεύσω, aor. ἐλῄστευσα, perf. desus.; pas. aor. ἐλῃστεύθην) 1 praticar a pirataria 2 saquear; roubar. 〈λῃστής〉</p></section></article>\n<article id=\"entry-dgp-25110\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λῃστήριον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 503 na letra λ · nº geral 25110</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 quadrilha de bandidos 2 antro de bandidos, de piratas 3 banditismo. 〈λῃστής〉</p></section></article>\n<article id=\"entry-dgp-25111\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λῃστής,</h1><div class=\"entry-meta\"><span>DGP · ordem 504 na letra λ · nº geral 25111</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. ληϊστής, οῦ (ὁ) 1 ladrão; bandido 2 pirata 3 usurpador: λῃστὴς τυραννίδος sóf. usurpador da realeza.</p></section></article>\n<article id=\"entry-dgp-25112\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λῃστικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 505 na letra λ · nº geral 25112</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 inclinado ao banditismo ♦ ἡ λῃστική 2 banditismo ♦ τὸ λῃστικόν 3 pirataria 4 quadrilha de bandidos. 〈λῃστής〉</p></section></article>\n<article id=\"entry-dgp-25113\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λῃστικῶς</h1><div class=\"entry-meta\"><span>DGP · ordem 506 na letra λ · nº geral 25113</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. à maneira dos bandidos ou dos piratas.</p></section></article>\n<article id=\"entry-dgp-25114\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λῆστις</h1><div class=\"entry-meta\"><span>DGP · ordem 507 na letra λ · nº geral 25114</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">só nom. e ac. (ἡ) poét. esquecimento.</p></section></article>\n<article id=\"entry-dgp-25115\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λῃστρικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 508 na letra λ · nº geral 25115</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 de bandido ou de pirata ♦ τὸ λῃσ­τρικόν 2 nave de pirata 3 bando de piratas. 〈λῃστής〉</p></section></article>\n<article id=\"entry-dgp-25116\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λῃστρικῶς</h1><div class=\"entry-meta\"><span>DGP · ordem 509 na letra λ · nº geral 25116</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. como bandidos ou piratas.</p></section></article>\n<article id=\"entry-dgp-25117\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λῃστρίς, ίδος</h1><div class=\"entry-meta\"><span>DGP · ordem 510 na letra λ · nº geral 25117</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fem.) 1 de bandido ou de pirata: ναῦς λῃστρίς navio de pirata 2 que vive de banditismo: λῃστρὶς γυνή plut. mulher ladra, pirata ♦ ἡ λῃστρίς 3 navio de pirata. 〈ληϊζομαι〉</p></section></article>\n<article id=\"entry-dgp-25118\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λήσω, λήσομαι</h1><div class=\"entry-meta\"><span>DGP · ordem 511 na letra λ · nº geral 25118</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. λανθάνω.</p></section></article>\n<article id=\"entry-dgp-25119\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Λητογένεια,</h1><div class=\"entry-meta\"><span>DGP · ordem 512 na letra λ · nº geral 25119</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">dór. Λατογένεια, ας (ἡ) filha de Leto, epít. de Ártemis. 〈Λητώ, γένος〉</p></section></article>\n<article id=\"entry-dgp-25120\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Λητοΐδης, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 513 na letra λ · nº geral 25120</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">filho de Leto, epít. de Apolo. 〈Λητώ〉</p></section></article>\n<article id=\"entry-dgp-25121\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λῃτουργέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 514 na letra λ · nº geral 25121</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">λειτουργέω.</p></section></article>\n<article id=\"entry-dgp-25122\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λῃτουργία</h1><div class=\"entry-meta\"><span>DGP · ordem 515 na letra λ · nº geral 25122</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">λειτουργία.</p></section></article>\n<article id=\"entry-dgp-25123\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Λητώ, οῦς (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 516 na letra λ · nº geral 25123</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Leto, mãe de Apolo e de Ártemis.</p></section></article>\n<article id=\"entry-dgp-25124\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Λητῷος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 517 na letra λ · nº geral 25124</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de Leto: Λητῴα κόρη filha de Leto, epít. de Ártemis. 〈Λητώ〉</p></section></article>\n<article id=\"entry-dgp-25125\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ληφθῆναι</h1><div class=\"entry-meta\"><span>DGP · ordem 518 na letra λ · nº geral 25125</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">inf. aor. pas. de λαμβάνω.</p></section></article>\n<article id=\"entry-dgp-25126\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λῆψις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 519 na letra λ · nº geral 25126</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 ação de tomar, de apoderar-se de, gen. 2 ação de receber; recebimento; aquisição: λ. μισθοῦ plat. recebimento de salário 3 pl. receitas; rendimentos 4 acesso; ataque (de doença) 5 Ret. proposta; tese a defender 6 escolha de um assunto.</p></section></article>\n<article id=\"entry-dgp-25127\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λήψομαι</h1><div class=\"entry-meta\"><span>DGP · ordem 520 na letra λ · nº geral 25127</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">fut. de λαμβάνω.</p></section></article>\n<article id=\"entry-dgp-25128\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λιάζω</h1><div class=\"entry-meta\"><span>DGP · ordem 521 na letra λ · nº geral 25128</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">at. só impf. 1 afrouxar ♦ ger. pas. λιάζομαι (fut. λιασ­θήσομαι, aor. ἐλιάσθην, perf. λελίασμαι, m.-q.-perf. ἐλε­λιάσμην) 2 desviar-se; afastar-se; distanciar-se de, ἐκ ou ἀπό e gen.: ἀπὸ πυρκαϊῆς ἑτέρωσε λιασθείς hom. afastando-se de uma pira numa outra direção, ἀμφὶ δ’ ἄρα σφι λιάζετο κῦμα hom. a onda se afastava em redor delas, σπουδῇ πρός σ’ ἐλιάσθην τὰς δεσποσύνους σκηνὰς προλιποῦσ(α) eur. com pressa esquivei-me para junto de ti, tendo deixado as tendas senhoris, λιάσθη ἐς πνοιὰς ἀνέμων hom. [a visão] se desvanece ao sopro dos ventos 3 precipitar-se; cair: πρηνὴς ἐλιάσθη hom. caiu para frente, πτερὰ λίασθεν hom. as asas cairam pendentes.</p></section></article>\n<article id=\"entry-dgp-25129\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λίαν,</h1><div class=\"entry-meta\"><span>DGP · ordem 522 na letra λ · nº geral 25129</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. λίην adv. 1 inteiramente; excessivamente; muito: λίην ἄχθομαι ἕλκος hom. a ferida dói muito, λίην πιστεύειν her. confiar excessivamente, μὴ λίαν στένε sóf. não te lamentes em demasia, λίην μέγα hom. muito grande; λίην τόσον hom. a um ponto tão extraordinário, λίαν ἑκάς hom. muito longe, οὐδέ τι λίαν οὕτω νώνυμος hom. não totalmente conhecida assim, λίαν βέλτιστα plat. completamente, perfeitamente ♦ καὶ λίην 2 enfático, em início de or., certamente; sem dúvida ♦ entre art. e subst. 3 em excesso; excessivo; muito grande: ἡ λίαν φιλότης ésql. o amor excessivo, αἱ λίαν ἀνεπιστημοσύναι xen. a excessiva ignorância ♦ τὸ λίαν 4 o excesso; a violência.</p></section></article>\n<article id=\"entry-dgp-25130\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λιαρός, ά, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 523 na letra λ · nº geral 25130</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 quente; tépido 2 doce; agradável.</p></section></article>\n<article id=\"entry-dgp-25131\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λίασθεν</h1><div class=\"entry-meta\"><span>DGP · ordem 524 na letra λ · nº geral 25131</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">3ª pl. aor. pas. ép. de λιάζω.</p></section></article>\n<article id=\"entry-dgp-25132\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λίβα</h1><div class=\"entry-meta\"><span>DGP · ordem 525 na letra λ · nº geral 25132</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ac. de λίψ.</p></section></article>\n<article id=\"entry-dgp-25133\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λιβάδιον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 526 na letra λ · nº geral 25133</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 pequena fonte 2 pequeno curso d’água. 〈λιβάς〉</p></section></article>\n<article id=\"entry-dgp-25134\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Λιβανῖτις, ιδος (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 527 na letra λ · nº geral 25134</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Afrodite do Líbano. 〈Λίβανος〉</p></section></article>\n<article id=\"entry-dgp-25135\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λίβανος, ου (ὁ</h1><div class=\"entry-meta\"><span>DGP · ordem 528 na letra λ · nº geral 25135</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e ἡ) 1 masc., árvore do incenso 2 masc. ou fem., incenso; resina aromática ♦ ὁ Λίβανος 3 Líbano, montanha da Síria.</p></section></article>\n<article id=\"entry-dgp-25136\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λιβανωτός, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 529 na letra λ · nº geral 25136</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 incenso: χόνδρος λιβανωτοῦ luc. grão de incenso 2 mercado de incenso 3 bíbl. turíbulo. 〈λίβανος〉</p></section></article>\n<article id=\"entry-dgp-25137\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λιβανωτοφόρος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 530 na letra λ · nº geral 25137</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que produz incenso. 〈λιβανωτός, φέρω〉</p></section></article>\n<article id=\"entry-dgp-25138\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λιβανωτρίς, ίδος (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 531 na letra λ · nº geral 25138</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">turíbulo. 〈λίβανος〉</p></section></article>\n<article id=\"entry-dgp-25139\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λιβάς, άδος (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 532 na letra λ · nº geral 25139</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 qualquer líquido que goteja 2 fonte; rio; corrente de água 3 lugar onde se espraiam as águas; lugar úmido; prado.</p></section></article>\n<article id=\"entry-dgp-25140\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λιβερτῖνος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 533 na letra λ · nº geral 25140</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">escravo liberto, filho de um liberto. [lat.]</p></section></article>\n<article id=\"entry-dgp-25141\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λίβος, εος-ους (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 534 na letra λ · nº geral 25141</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 gota de líquido 2 pl. lágrimas 3 espécie de doce.</p></section></article>\n<article id=\"entry-dgp-25142\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λιβός</h1><div class=\"entry-meta\"><span>DGP · ordem 535 na letra λ · nº geral 25142</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">gen. de λίψ.</p></section></article>\n<article id=\"entry-dgp-25143\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Λιβύα</h1><div class=\"entry-meta\"><span>DGP · ordem 536 na letra λ · nº geral 25143</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">dór. = Λιβύη.</p></section></article>\n<article id=\"entry-dgp-25144\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Λιβύη, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 537 na letra λ · nº geral 25144</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">a Líbia; a África. 〈Λίβυς〉</p></section></article>\n<article id=\"entry-dgp-25145\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Λιβύηθε</h1><div class=\"entry-meta\"><span>DGP · ordem 538 na letra λ · nº geral 25145</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. proveniente da Líbia. 〈Λιβύη, -θε〉</p></section></article>\n<article id=\"entry-dgp-25146\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Λιβυκός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 539 na letra λ · nº geral 25146</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">da Líbia: Λιβυκοὶ λόγοι artt. narrativas líbias, espécie de fábulas como as de Esopo. 〈Λιβύη〉</p></section></article>\n<article id=\"entry-dgp-25147\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Λίβυς, υος</h1><div class=\"entry-meta\"><span>DGP · ordem 540 na letra λ · nº geral 25147</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc.) 1 da Líbia; líbio ♦ οἱ Λίβυες 2 os líbios.</p></section></article>\n<article id=\"entry-dgp-25148\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Λιβυστικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 541 na letra λ · nº geral 25148</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">da Líbia. 〈Λιβύη〉</p></section></article>\n<article id=\"entry-dgp-25149\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Λιβυστῖνος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 542 na letra λ · nº geral 25149</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Λιβυστικός.</p></section></article>\n<article id=\"entry-dgp-25150\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λίγα</h1><div class=\"entry-meta\"><span>DGP · ordem 543 na letra λ · nº geral 25150</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. = λιγέως.</p></section></article>\n<article id=\"entry-dgp-25151\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λιγαίνω</h1><div class=\"entry-meta\"><span>DGP · ordem 544 na letra λ · nº geral 25151</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 proclamar em alto e bom som 2 lamentar-se 3 cantar ♦ méd. 4 cantar 5 (corvo) gritar 6 cantar; celebrar ♦ pas. 7 tornar-se melodioso 8 estar inspirado. 〈λιγύς〉</p></section></article>\n<article id=\"entry-dgp-25152\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λίγγω</h1><div class=\"entry-meta\"><span>DGP · ordem 545 na letra λ · nº geral 25152</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só aor. 3ª sing. poét. λίγξε) ressoar com força; (a corda do arco) sibilar.</p></section></article>\n<article id=\"entry-dgp-25153\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λίγδην</h1><div class=\"entry-meta\"><span>DGP · ordem 546 na letra λ · nº geral 25153</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. superficialmente.</p></section></article>\n<article id=\"entry-dgp-25154\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λίγεια</h1><div class=\"entry-meta\"><span>DGP · ordem 547 na letra λ · nº geral 25154</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">fem. de λιγύς.</p></section></article>\n<article id=\"entry-dgp-25155\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λιγέως</h1><div class=\"entry-meta\"><span>DGP · ordem 548 na letra λ · nº geral 25155</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. 1 com voz aguda: λ. κλαίειν hom. lamentar-se com gritos penetrantes 2 com voz clara ou harmoniosa. 〈λιγύς〉</p></section></article>\n<article id=\"entry-dgp-25156\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λιγνύς, ύος (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 549 na letra λ · nº geral 25156</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 chama fuliginosa 2 fuligem.</p></section></article>\n<article id=\"entry-dgp-25157\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λίγξε</h1><div class=\"entry-meta\"><span>DGP · ordem 550 na letra λ · nº geral 25157</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. λίγγω.</p></section></article>\n<article id=\"entry-dgp-25158\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λιγυπνείων, οντος</h1><div class=\"entry-meta\"><span>DGP · ordem 551 na letra λ · nº geral 25158</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc.) de sopro harmonioso ou estridente. 〈λιγύς, πνέω〉</p></section></article>\n<article id=\"entry-dgp-25159\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λιγυρίζω</h1><div class=\"entry-meta\"><span>DGP · ordem 552 na letra λ · nº geral 25159</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cantar com voz melodiosa. 〈λιγυρός〉</p></section></article>\n<article id=\"entry-dgp-25160\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λιγυρός, ά, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 553 na letra λ · nº geral 25160</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que emite som agudo ou sibilante 2 claro; melodioso; harmonioso (som, canto) 3 afável nos relacionamentos 4 flexível ♦ λιγυρά adv. 5 melodiosamente. 〈λιγύς〉</p></section></article>\n<article id=\"entry-dgp-25161\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λιγυρῶς</h1><div class=\"entry-meta\"><span>DGP · ordem 554 na letra λ · nº geral 25161</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. com som claro ou melodioso; harmoniosamente.</p></section></article>\n<article id=\"entry-dgp-25162\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λιγύς, λίγεια, λιγύ</h1><div class=\"entry-meta\"><span>DGP · ordem 555 na letra λ · nº geral 25162</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 de som claro, agudo, penetrante 2 melodioso; harmonioso (voz, som) 3 eloqüente; diserto; facundo.</p></section></article>\n<article id=\"entry-dgp-25163\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Λίγυς, υος (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 556 na letra λ · nº geral 25163</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">habitante da Ligúria, lígure.</p></section></article>\n<article id=\"entry-dgp-25164\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Λιγυστῖνος, η, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 557 na letra λ · nº geral 25164</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 da Ligúria ♦ οἱ Λιγυστῖνοι 2 os lígu­res. 〈Λίγυς〉</p></section></article>\n<article id=\"entry-dgp-25165\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λιγύφθογγος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 558 na letra λ · nº geral 25165</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de voz clara ou harmoniosa; de som agudo. 〈λιγύς, φθέγγομαι〉</p></section></article>\n<article id=\"entry-dgp-25166\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λιγύφωνος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 559 na letra λ · nº geral 25166</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de voz clara, sonora ou harmoniosa. 〈λιγύς, φωνή〉</p></section></article>\n<article id=\"entry-dgp-25167\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λίην</h1><div class=\"entry-meta\"><span>DGP · ordem 560 na letra λ · nº geral 25167</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. = λίαν.</p></section></article>\n<article id=\"entry-dgp-25168\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λιθάζω</h1><div class=\"entry-meta\"><span>DGP · ordem 561 na letra λ · nº geral 25168</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 lançar pedras 2 lançar como se fosse pedra 3 bíbl. apedrejar; lapidar. 〈λίθος〉</p></section></article>\n<article id=\"entry-dgp-25169\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λίθαξ, ακος</h1><div class=\"entry-meta\"><span>DGP · ordem 562 na letra λ · nº geral 25169</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc., fem.) 1 de pedra; rochoso ♦ ἡ λίθαξ 2 pedregulho 3 pedra tumular; lápide 4 pedra preciosa 5 pedra-pomes 6 pl. região pedregosa. 〈λίθος〉</p></section></article>\n<article id=\"entry-dgp-25170\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λιθάς, άδος (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 563 na letra λ · nº geral 25170</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 pedra pequena 2 chuva de pedras; granizo; saraiva. 〈λίθος〉</p></section></article>\n<article id=\"entry-dgp-25171\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λίθεος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 564 na letra λ · nº geral 25171</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de pedra. 〈λίθος〉</p></section></article>\n<article id=\"entry-dgp-25172\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λιθίδιον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 565 na letra λ · nº geral 25172</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 pedrinha 2 pedra preciosa; gema 3 Medic. cálculo da visícula. 〈λίθος〉</p></section></article>\n<article id=\"entry-dgp-25173\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λίθινος, η, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 566 na letra λ · nº geral 25173</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 de pedra 2 que petrifica: λ. θάνατος pínd. morte que petrifica com a cabeça da Górgona 3 petrificado; duro; insensível: ἡ καρδία ἡ λιθίνη sept. coração petrificado ♦ τὰ λίθινα 4 estátuas de mármore. 〈λίθος〉</p></section></article>\n<article id=\"entry-dgp-25174\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λιθίνως</h1><div class=\"entry-meta\"><span>DGP · ordem 567 na letra λ · nº geral 25174</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv., em λ. βλέπειν xen. olhar fixamente para alguém, πρός e ac.</p></section></article>\n<article id=\"entry-dgp-25175\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λιθοβολέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 568 na letra λ · nº geral 25175</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">apedrejar; lapidar. 〈λιθοβόλος〉</p></section></article>\n<article id=\"entry-dgp-25176\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λιθοβόλος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 569 na letra λ · nº geral 25176</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que lança pedras ♦ ὁ λιθοβόλος 2 máquina de arremessar pedras. 〈λίθος, βάλλω〉</p></section></article>\n<article id=\"entry-dgp-25177\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λιθογλύφος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 570 na letra λ · nº geral 25177</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">escultor; estatuário; entalhador. 〈λί­θος, γλύφω〉</p></section></article>\n<article id=\"entry-dgp-25178\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λιθόδερμος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 571 na letra λ · nº geral 25178</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de pele ou escama dura como pedra. 〈λίθος, δέρμα〉</p></section></article>\n<article id=\"entry-dgp-25179\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λιθοδόμος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 572 na letra λ · nº geral 25179</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">aquele que constrói com pedras; pedreiro. 〈λίθος, δέμω〉</p></section></article>\n<article id=\"entry-dgp-25180\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λιθοκόλλητος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 573 na letra λ · nº geral 25180</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 ligado com cimento, i.e., bem cimentado 2 muito duro 3 incrustado de pedras preciosas. 〈λίθος, κολλάω〉</p></section></article>\n<article id=\"entry-dgp-25181\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λιθόλευστος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 574 na letra λ · nº geral 25181</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 apedrejado; lapidado 2 resultado de apedrejamento, de lapidação: λιθόλευστον Ἄρη sóf. Ares que mata por lapidação, morte causada por lapidação 3 digno de ser apedrejado. 〈λίθος, λεύω〉</p></section></article>\n<article id=\"entry-dgp-25182\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λιθολόγημα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 575 na letra λ · nº geral 25182</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">construção de pedras; alicerce; muro. 〈λιθολόγος〉</p></section></article>\n<article id=\"entry-dgp-25183\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λιθολόγος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 576 na letra λ · nº geral 25183</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">aquele que reúne ou escolhe pedras para construção; pedreiro. 〈λίθος, λέγω1〉</p></section></article>\n<article id=\"entry-dgp-25184\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λιθοξόος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 577 na letra λ · nº geral 25184</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">talhador de pedras; escultor. 〈λίθος, ξέω〉</p></section></article>\n<article id=\"entry-dgp-25185\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λιθοποιός, ός, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 578 na letra λ · nº geral 25185</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que petrifica 2 que produz pedra. 〈λίθος, ποιέω〉</p></section></article>\n<article id=\"entry-dgp-25186\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λίθος, ου (ὁ</h1><div class=\"entry-meta\"><span>DGP · ordem 579 na letra λ · nº geral 25186</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e ἡ) 1 pedra: λίθον τινὰ ποιῆσαι hom. transformar alguém em bloco de pedra, θεῖναι λίθον τι hom. transformar algo em pedra; como símbolo de insensibilidade, σοὶ δ’ αἰεὶ κραδίη στερεωτέρη ἐστὶ λίθοιο hom. teu coração é sempre mais duro que uma pedra, de estupidez ὥσπερ λίθον ζῆν plat. viver como uma pedra, de impossibilidade λίθον ἕψειν ar. cozinhar uma pedra 2 pedra preciosa 3 pedra tumular 4 espécie de peão para jogar 5 pl. região rochosa ♦ em Atenas 6 na Pnyx, pedra usada como púlpito pelo orador 7 na ágora, pedra usada como púlpito pelos arautos 8 na ágora, pedra usada como altar para juramentos ♦ masc. ou fem. 9 projétil; disco 10 mármore ♦ fem. 11 pedra de toque 12 pedra magnética; ímã 13 cálculo vesicular.</p></section></article>\n<article id=\"entry-dgp-25187\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λιθοσπαδής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 580 na letra λ · nº geral 25187</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">feito com a retirada de pedras. 〈λίθος, σπάω〉</p></section></article>\n<article id=\"entry-dgp-25188\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λιθόστρωτος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 581 na letra λ · nº geral 25188</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 construído em pedras 2 pavimentado em mosaico. 〈λίθος, στρώννυμι〉</p></section></article>\n<article id=\"entry-dgp-25189\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λιθοτομέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 582 na letra λ · nº geral 25189</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 talhar na pedra 2 talhar a pedra. 〈λίθος, τέμνω〉</p></section></article>\n<article id=\"entry-dgp-25190\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λιθοτομία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 583 na letra λ · nº geral 25190</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 talhe; corte de pedras 2 pedreira 3 pl. pedreiras de mármore 4 Medic. litotomia. 〈λίθος, τέμνω〉</p></section></article>\n<article id=\"entry-dgp-25191\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λιθουργός, ός, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 584 na letra λ · nº geral 25191</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que serve para trabalhar a pedra ♦ ὁ λιθουργός 2 talhador de pedras; escultor. 〈λίθος, ἔργον〉</p></section></article>\n<article id=\"entry-dgp-25192\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λιθοφορέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 585 na letra λ · nº geral 25192</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só pres.) carregar pedra ou pedras. 〈λίθος, φέρω〉</p></section></article>\n<article id=\"entry-dgp-25193\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λιθόω-ῶ,</h1><div class=\"entry-meta\"><span>DGP · ordem 586 na letra λ · nº geral 25193</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">só pas. λιθόομαι-οῦμαι transformar-se em pedra; petrificar-se. 〈λίθος〉</p></section></article>\n<article id=\"entry-dgp-25194\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λιθώδης, ης, ες</h1><div class=\"entry-meta\"><span>DGP · ordem 587 na letra λ · nº geral 25194</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 semelhante a uma pedra; duro como pedra 2 pedregoso. 〈λίθος, -ωδης〉</p></section></article>\n<article id=\"entry-dgp-25195\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λίθωσις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 588 na letra λ · nº geral 25195</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 arte de transformar em pedra 2 petrificação. 〈λιθόω〉</p></section></article>\n<article id=\"entry-dgp-25196\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λιθωτός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 589 na letra λ · nº geral 25196</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">feito em ou de pedra. 〈λιθόω〉</p></section></article>\n<article id=\"entry-dgp-25197\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λικμάω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 590 na letra λ · nº geral 25197</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. λικμήσω, aor. ἐλίκμησα, perf. desus.; pas. aor. ἐλικμήθην, perf. λελίκμημαι) 1 joeirar 2 espalhar. 〈λικμός〉</p></section></article>\n<article id=\"entry-dgp-25198\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λικμητήρ, ῆρος (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 591 na letra λ · nº geral 25198</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">joeireiro. 〈λικμάω〉</p></section></article>\n<article id=\"entry-dgp-25199\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λικμός, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 592 na letra λ · nº geral 25199</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">bíbl. joeira.</p></section></article>\n<article id=\"entry-dgp-25200\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λικνίτης, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 593 na letra λ · nº geral 25200</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">deus da joeira sagrada, Dioniso. 〈λῖκνον〉</p></section></article>\n";
